/*
 * Binary models generated by the Hawkins French-model pipeline (stage 3).
 * The ESP32-S3 MMU reads these read-only sections directly from mapped flash.
 * Keep these paths in sync with the stage-3 artifact publishing workflow.
 */
.section .rodata.hawkins_llm_model,"a",@progbits
.balign 16
.global hawkins_model_start
.type hawkins_model_start, @object
hawkins_model_start:
.incbin "src/hawkins_llm/assets/model_lecarnet_q4.bin"
.global hawkins_model_end
hawkins_model_end:

.section .rodata.hawkins_llm_tokenizer,"a",@progbits
.balign 16
.global hawkins_tokenizer_start
.type hawkins_tokenizer_start, @object
hawkins_tokenizer_start:
.incbin "src/hawkins_llm/assets/tokenizer_lecarnet_ctk2.bin"
.global hawkins_tokenizer_end
hawkins_tokenizer_end:
